pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a minimal ERC721 to use as the nft
        // Instead we'll just use a mock by deploying a simple ERC721 contract inline
        vm.etch(address(0x100), type(MockERC721).runtimeCode);
        MockERC721 mockNft = MockERC721(address(0x100));

        // Initialize the pool with the mock nft
        c.initialize(
            address(0),    // baseToken (ETH)
            address(mockNft), // nft
            1000e18,       // virtualBaseTokenReserves
            1000e18,       // virtualNftReserves
            0,             // changeFee
            0,             // feeRate
            bytes32(0),    // merkleRoot
            false,         // useStolenNftOracle
            false          // payRoyalties
        );

        // Mint tokenId 1 to this contract (the pool)
        mockNft.mint(address(c), 1);

        // Now call availableForFlashLoan on tokenId 1
        bool available = c.availableForFlashLoan(address(mockNft), 1);

        // In the correct version, nft is set correctly so the ownership check works
        // and returns true. In the buggy version, nft is address(0), so the call
        // to ownerOf on address(0) will revert and the function returns false.
        assertTrue(available == true, "Flash loan should be available");
    }
}

// Minimal ERC721 for testing
contract MockERC721 {
    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;

    function mint(address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        return _owners[tokenId];
    }

    function balanceOf(address owner) external view returns (uint256) {
        return _balances[owner];
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[from]--;
        _balances[to]++;
    }
}

